package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The paste box: an OPEN claim per pasted line, for a person already on the sheet. */
@Service
public class PasteService {

    /** An amount as the claim form takes it: up to twelve digits and two decimals, negative for a correction. */
    private static final java.util.regex.Pattern AMOUNT = java.util.regex.Pattern.compile("-?\\d{1,12}(\\.\\d{1,2})?");

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 1000;

    /** The longest external reference the claim form takes. */
    private static final int REF_MAX = 120;

    private final PersonRepository people;
    private final ClaimService claims;
    private final ClaimRepository claimStore;
    private final SheetService sheets;
    private final SheetRepository sheetStore;

    public PasteService(PersonRepository people, ClaimService claims, ClaimRepository claimStore, SheetService sheets,
            SheetRepository sheetStore) {
        this.people = people;
        this.claims = claims;
        this.claimStore = claimStore;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
    }

    /** A pasted line read into a claim's values. */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
    }

    /**
     * Put an OPEN claim per line of {@code text} (name,amount,date,note; the note may hold commas, a blank date
     * takes the sheet's entry date while set, else its today, the note may be absent), in order, for the person on the
     * sheet whose name or an alias matches (trimmed, ignoring case). Each line is checked by exactly the claim form's
     * rules. A line whose person, date and note match one of that person's claims as they stood before the paste (void
     * and deleted claims never match) updates that claim instead: the newest matching DRAFT takes the line's amount
     * (edited only when that changes it); a line whose matches include no DRAFT refuses the paste. Every claim added or
     * updated is then opened by the user exactly as the open button would, numbered in paste order. When any line or
     * open is refused, nothing is changed and nothing is recorded. Blank lines are skipped; a paste with no lines is
     * refused. A note ending in {@code " #<reference>"} gives the claim that external reference, which is not part of
     * the note; a reference used on the sheet or on an earlier line, without regard to case, refuses the paste.
     * The claims, as opened, in paste order.
     */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (String raw : text.split("\\r?\\n")) {
            if (!raw.isBlank()) {
                Line line = read(sheetId, raw);
                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
                    throw ClaimService.refUsed(line.ref());
                }
                lines.add(line);
            }
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findById(sheetId).orElseThrow();
        List<Claim> before = claimStore.findBySheetIdOrderByListedDescIdDesc(sheetId);
        List<Claim> matched = new ArrayList<>();
        for (Line line : lines) {
            matched.add(match(before, line, line.date() != null ? line.date() : sheet.defaultClaimDate()));
        }
        List<Claim> opened = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            Line line = lines.get(i);
            Claim draft = matched.get(i);
            long id;
            if (draft == null) {
                id = claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
                        line.ref()).getId();
            } else {
                id = draft.getId();
                Claim now = claimStore.findByIdAndSheetId(id, sheetId).orElseThrow();
                if (now.getAmount().compareTo(line.amount()) != 0 || line.ref() != null) {
                    claims.update(sheetId, user, id, line.amount(), now.getDate(), now.getNote(), now.getCorrects(),
                            line.ref() != null ? line.ref() : now.getRef(), now.getTags());
                }
            }
            opened.add(claims.changeStatus(sheetId, user, id, ClaimStatus.OPEN));
        }
        return opened;
    }

    /** The newest DRAFT among the person's claims (newest first, as listed) matching the line's date and note; null
     *  when none match. Refused when claims match but none is a DRAFT. */
    private static Claim match(List<Claim> before, Line line, LocalDate date) {
        boolean any = false;
        for (Claim claim : before) {
            if (claim.getPersonId() != line.person().getId().longValue()
                    || claim.getStatus() == ClaimStatus.VOID || claim.getStatus() == ClaimStatus.DELETED
                    || !date.equals(claim.getDate()) || !line.note().trim().equals(claim.getNote())) {
                continue;
            }
            if (claim.getStatus() == ClaimStatus.DRAFT) {
                return claim;
            }
            any = true;
        }
        if (any) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A pasted line matches a claim of its person that is no longer a draft");
        }
        return null;
    }

    private Line read(String sheetId, String raw) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 2) {
            throw refused("Each line needs at least a name and an amount");
        }
        String name = fields[0].trim();
        if (name.isEmpty()) {
            throw refused("Each line needs a name");
        }
        Person person = people.findBySheetIdAndNameOrAliasIgnoreCase(sheetId, name)
                .orElseThrow(() -> refused("No one named " + name + " is on this sheet"));
        String amount = fields[1].trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw refused("An amount takes up to two decimals");
        }
        LocalDate date = null;
        String dateText = fields.length > 2 ? fields[2].trim() : "";
        if (!dateText.isEmpty()) {
            try {
                date = LocalDate.parse(dateText);
            } catch (DateTimeParseException e) {
                throw refused("A date is written yyyy-mm-dd");
            }
        }
        String note = fields.length > 3 ? fields[3] : "";
        if (note.length() > NOTE_MAX) {
            throw refused("A note is at most " + NOTE_MAX + " characters");
        }
        String ref = null;
        String trimmed = note.trim();
        int hash = trimmed.lastIndexOf(" #");
        if (hash >= 0 && !trimmed.substring(hash + 2).isBlank()) {
            ref = ClaimService.refOf(trimmed.substring(hash + 2));
            note = trimmed.substring(0, hash);
        }
        if (ref != null && ref.length() > REF_MAX) {
            throw refused("A reference is at most " + REF_MAX + " characters");
        }
        return new Line(person, new BigDecimal(amount), date, note, ref);
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The periods of a sheet. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;
    private final Rollup rollup;
    private final RoleService roles;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetStore, Audit audit,
            Rollup rollup, RoleService roles) {
        this.roles = roles;
        this.periods = periods;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The sheet's periods, by from-date. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    /** Add a period; the name is stored trimmed. Refused when the name is in use on the sheet, the
     *  to-date is before the from-date, or it shares a day with another period of the sheet. With no
     *  from-date it starts on the sheet's today. A cap, when given, is the most OPEN or PENDING claims a person may
     *  have in it. */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate fromDate, LocalDate to, Integer cap) {
        sheets.load(sheetId, user);
        // The sheet is locked so two periods added at the same moment cannot overlap.
        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
        LocalDate from = fromDate != null ? fromDate : today;
        String trimmed = name.trim();
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
    public Period softClose(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        if (!sheet.allows("close", roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        period.softClose(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedByPerson(sheetId, period));
        Period closed = periods.saveAndFlush(period);
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period="
                + closed.getName() + " total=" + closed.getClosedTotal().toPlainString());
        return closed;
    }

    /** Close, in order of their to-dates, every open period of the sheet whose to-date plus its grace days is
     *  before its today, each exactly as a close by hand. Called with the sheet locked, once its new today is set. */
    @Transactional
    public void closePastGrace(Sheet sheet, String user) {
        if (sheet.getGraceDays() == null) {
            return;
        }
        periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && sheet.pastGrace(p.getToDate()))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> closeAndRecord(sheet.getId(), user, p, " auto=yes"));
    }

    /** Fix a period's due-total as it is now and record the close; the audit line ends with the suffix given. */
    private Period closeAndRecord(String sheetId, String user, Period period, String suffix) {
        period.close(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedByPerson(sheetId, period));
        Period closed = periods.saveAndFlush(period);
        BigDecimal total = closed.getClosedTotal();
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + closed.getName()
                + " total=" + total.toPlainString() + suffix);
        return closed;
    }

    /** Reopen a closed or soft-closed period, making its due-total live again; only a role the permission matrix allows may (by
     *  default a steward), and it is refused when the period is open. */
    @Transactional
    public Period reopen(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        if (!sheet.allows("reopen", roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
